import React, { useEffect, useState } from "react";
import { auth } from "../../firebase";
import { useNavigate } from "react-router-dom";
import NavBar from "../../Components/AdminNav";
import "./adminDashboard.css";

const coursesList = [
  "Blouse Course",
  "Frocks Course",
  "Skirt Course",
  "Dress Course",
  "Pants Course",
]; // Example courses

export default function AdminDashboard() {
  const [users, setUsers] = useState([]);
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);
  const [editingUser, setEditingUser] = useState(null);
  const [editEmail, setEditEmail] = useState("");
  const [viewUser, setViewUser] = useState(null); // For view details popup
  const [selectedCourses, setSelectedCourses] = useState([]);

  const [currentPage, setCurrentPage] = useState(1);
  const usersPerPage = 10;

  const navigate = useNavigate();
  const API_BASE_URL = "http://localhost:5000";

  useEffect(() => {
    const user = auth.currentUser;
    if (!user || user.email !== "yasasmigunasinghe@gmail.com") {
      navigate("/account");
    }
  }, [navigate]);

  const fetchUsers = async () => {
    setLoading(true);
    setError("");
    try {
      const res = await fetch(`${API_BASE_URL}/users`);
      if (!res.ok) {
        const text = await res.text();
        throw new Error(`Failed to fetch users: ${res.status} ${text}`);
      }
      const data = await res.json();
      setUsers(data);
      setCurrentPage(1); // Reset to first page after fetching users
    } catch (err) {
      setError(err.message);
    }
    setLoading(false);
  };

  useEffect(() => {
    fetchUsers();
  }, []);

  const handleDelete = async (uid) => {
    setError("");
    try {
      const res = await fetch(`${API_BASE_URL}/users/${uid}`, {
        method: "DELETE",
      });
      if (!res.ok) {
        const text = await res.text();
        throw new Error(`Failed to delete user: ${res.status} ${text}`);
      }
      fetchUsers();
    } catch (err) {
      setError(err.message);
    }
  };

  const startEdit = (user) => {
    setEditingUser(user);
    setEditEmail(user.email);
  };

  const cancelEdit = () => {
    setEditingUser(null);
    setError("");
  };

  const submitEdit = async () => {
    try {
      const res = await fetch(`${API_BASE_URL}/users/${editingUser.uid}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email: editEmail }),
      });
      if (!res.ok) {
        const text = await res.text();
        throw new Error(`Failed to update user: ${res.status} ${text}`);
      }
      setEditingUser(null);
      fetchUsers();
    } catch (err) {
      setError(err.message);
    }
  };

  const handleAccept = async (uid) => {
    setError("");
    try {
      const res = await fetch(`${API_BASE_URL}/users/accept/${uid}`, {
        method: "POST",
      });
      if (!res.ok) {
        const text = await res.text();
        throw new Error(`Failed to accept user: ${res.status} ${text}`);
      }
      fetchUsers();
    } catch (err) {
      setError(err.message);
    }
  };

  // Show view details modal and initialize selected courses
  const openViewDetails = (user) => {
    setViewUser(user);
    // Initialize selected courses from user data if exists or empty array
    setSelectedCourses(user.courses || []);
  };

  const closeViewDetails = () => {
    setViewUser(null);
    setSelectedCourses([]);
    setError("");
  };

  // Toggle course selection
  const toggleCourse = (course) => {
    if (selectedCourses.includes(course)) {
      setSelectedCourses(selectedCourses.filter((c) => c !== course));
    } else {
      setSelectedCourses([...selectedCourses, course]);
    }
  };

  // Save course access for user
  const saveCourseAccess = async () => {
    try {
      const res = await fetch(`${API_BASE_URL}/users/${viewUser.uid}/courses`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ courses: selectedCourses }),
      });
      if (!res.ok) {
        const text = await res.text();
        throw new Error(`Failed to save courses: ${res.status} ${text}`);
      }
      // Optionally accept user on saving courses
      await handleAccept(viewUser.uid);
      closeViewDetails();
      fetchUsers();
    } catch (err) {
      setError(err.message);
    }
  };

  // Pagination logic
  const totalPages = Math.ceil(users.length / usersPerPage);
  const startIndex = (currentPage - 1) * usersPerPage;
  const currentUsers = users.slice(startIndex, startIndex + usersPerPage);

  const handleNext = () => {
    if (currentPage < totalPages) setCurrentPage(currentPage + 1);
  };

  const handleBack = () => {
    if (currentPage > 1) setCurrentPage(currentPage - 1);
  };

  return (
    <>
      <NavBar />

      <div className="admin-container">
        <h2>Admin User Management</h2>
        {error && <p className="error-message">{error}</p>}
        {loading ? (
          <p>Loading users...</p>
        ) : (
          <>
            <table className="admin-table">
              <thead>
                <tr>
                  <th>Email</th>
                  <th>Username</th>
                  <th>WhatsApp Number</th>
                  <th>Accepted</th>
                  <th>Actions</th>
                </tr>
              </thead>
              <tbody>
                {currentUsers.length === 0 ? (
                  <tr>
                    <td colSpan="5" style={{ textAlign: "center" }}>
                      No users found
                    </td>
                  </tr>
                ) : (
                  currentUsers.map((user) => (
                    <tr key={user.uid}>
                      <td>{user.email}</td>
                      <td>{user.username || "-"}</td>
                      <td>{user.whatsapp || "-"}</td>
                      <td>{user.accepted ? "Yes" : "No"}</td>
                      <td>
                        <div className="action-buttons">
                          <button className="btn-edit" onClick={() => startEdit(user)}>
                            Edit
                          </button>
                          <button className="btn-delete" onClick={() => handleDelete(user.uid)}>
                            Delete
                          </button>
                        </div>

                        {!user.accepted && (
                          <button
                            className="btn-accept"
                            onClick={() => openViewDetails(user)}
                            style={{ marginTop: "0.5rem" }}
                          >
                            View Details
                          </button>
                        )}
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>

            {/* Pagination Controls */}
            <div className="pagination-controls" style={{ marginTop: "1rem", textAlign: "center" }}>
              <button onClick={handleBack} disabled={currentPage === 1}>
                Back
              </button>
              <span style={{ margin: "0 1rem" }}>
                Page {currentPage} of {totalPages}
              </span>
              <button onClick={handleNext} disabled={currentPage === totalPages}>
                Next
              </button>
            </div>
          </>
        )}

        {/* Edit Modal */}
        {editingUser && (
          <div className="modal-overlay">
            <div className="modal-content">
              <h3>Edit User</h3>
              <input
                type="email"
                value={editEmail}
                onChange={(e) => setEditEmail(e.target.value)}
              />
              <div className="modal-buttons">
                <button className="btn-save" onClick={submitEdit}>
                  Save
                </button>
                <button className="btn-cancel" onClick={cancelEdit}>
                  Cancel
                </button>
              </div>
            </div>
          </div>
        )}

        {/* View Details / Course Access Modal */}
        {viewUser && (
          <div className="modal-overlay">
            <div className="modal-content">
              <h3>User Details</h3>
              <p>
                <strong>Name:</strong> {viewUser.username || "-"}
              </p>
              <p>
                <strong>Email:</strong> {viewUser.email}
              </p>
              <p>
                <strong>WhatsApp Number:</strong> {viewUser.whatsapp || "-"}
              </p>

              <h4>Assign Courses</h4>
              <div className="courses-list">
                {coursesList.map((course) => (
                  <div key={course}>
                    <label>
                      <input
                        type="checkbox"
                        checked={selectedCourses.includes(course)}
                        onChange={() => toggleCourse(course)}
                      />
                      {course}
                    </label>
                  </div>
                ))}
              </div>

              <div className="modal-buttons" style={{ marginTop: "1rem" }}>
                <button className="btn-save" onClick={saveCourseAccess}>
                  Accept and Save
                </button>
                <button className="btn-cancel" onClick={closeViewDetails}>
                  Cancel
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    </>
  );
}
